function draw(ctx, width, height) {
  // ---------- Static state ----------
  // Initialize once
  if (!draw._init) {
    // Build a static skyline
    const buildingCount = Math.floor(width / 30); // ~30px per building
    draw.buildings = [];
    for (let i = 0; i < buildingCount; i++) {
      const bw = 20 + Math.random() * 60;          // 20‑80px wide
      const bh = 0.4 + Math.random() * 0.6;        // 40‑100% of canvas height
      const x = i * 30 + Math.random() * 10;       // slight horizontal jitter
      const y = height * (1 - bh);                 // top position
      const grad = ctx.createLinearGradient(x, height, x, y);
      grad.addColorStop(0, '#ff00ff');             // purple
      grad.addColorStop(1, '#00ffff');             // cyan
      draw.buildings.push({ x, y, w: bw, h: bh * height, grad });
    }

    // Create rain drops
    const rainCount = 200;
    draw.rain = [];
    for (let i = 0; i < rainCount; i++) {
      draw.rain.push({
        x: Math.random() * width,
        y: Math.random() * height,
        len: 5 + Math.random() * 10,
        speed: 4 + Math.random() * 6
      });
    }

    draw._init = true;
  }

  // ---------- Draw background ----------
  ctx.fillStyle = '#0a0a0c';
  ctx.fillRect(0, 0, width, height);

  // ---------- Draw skyline ----------
  for (const b of draw.buildings) {
    ctx.fillStyle = b.grad;
    ctx.fillRect(b.x, b.y, b.w, b.h);
  }

  // ---------- Draw rain ----------
  ctx.strokeStyle = 'rgba(255,255,255,0.15)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (const r of draw.rain) {
    r.y += r.speed;
    if (r.y > height) r.y = -r.len;
    ctx.moveTo(r.x, r.y);
    ctx.lineTo(r.x, r.y + r.len);
  }
  ctx.stroke();
}
