        { bright: '#a020f0', dark: '#4b0082' }, // Bright purple to darker purple
        { bright: '#00ffff', dark: '#008b8b' }  // Bright cyan to darker cyan
    ];

    for (let i = 0; i < numBuildings; i++) {
        const buildingWidth = Math.random() * (maxBuildingWidth - minBuildingWidth) + minBuildingWidth;
        const buildingHeight = Math.random() * (maxBuildingHeight - minBuildingHeight) + minBuildingHeight;
        const x = Math.random() * (width - buildingWidth); // Random X position
        const y = height - buildingHeight; // Buildings start from the bottom of the canvas

        // Randomly pick a neon color set
        const colorSet = neonColors[Math.floor(Math.random() * neonColors.length)];

        // Create a vertical linear gradient for the building to simulate neon glow
        const buildingGradient = ctx.createLinearGradient(x, y, x, y + buildingHeight);
        buildingGradient.addColorStop(0, colorSet.bright); // Brightest at the top of the building
        buildingGradient.addColorStop(0.7, colorSet.dark);  // Fades to a darker shade
        // Blend the very bottom of the building with the background color for a subtle fade
        buildingGradient.addColorStop(1, 'rgba(10,10,12,0.1)'); 

