    // This gradient will overlay the bottom part of the buildings
    const hazeGradient = ctx.createLinearGradient(0, height * 0.6, 0, height);
    hazeGradient.addColorStop(0, 'rgba(10, 10, 12, 0)'); // Transparent at 60% height
    hazeGradient.addColorStop(1, '#0a0a0c'); // Fades to background color at the bottom
    ctx.fillStyle = hazeGradient;
    ctx.fillRect(0, 0, width, height);

    // 4. Rain effects
    const numRainDrops = 150; // Number of rain streaks
    ctx.strokeStyle = 'rgba(180, 200, 255, 0.6)'; // Light blue-white, translucent color for rain
    ctx.lineWidth = 1; // Thin lines for rain streaks
    const rainLength = 15; // Length of each rain streak
    // Diagonal angle for rain (e.g., 135 degrees for falling from top-right to bottom-left)
    const rainAngle = Math.PI * 0.75; 

