        ctx.beginPath();
        ctx.moveTo(x, y);
        // Draw the rain streak at the calculated angle
        ctx.lineTo(x + rainLength * Math.cos(rainAngle), y + rainLength * Math.sin(rainAngle));
        ctx.stroke();
