  // Draw skyscrapers
  for (let i = 0; i < 20; i++) {
    const x = Math.random() * width;
    const w = Math.random() * 50 + 20;
    const h = Math.random() * (height / 2) + height / 4;
    const gradient = ctx.createLinearGradient(x, height, x, height - h);
    gradient.addColorStop(0, gradientColors[Math.floor(Math.random() * gradientColors.length)]);
    gradient.addColorStop(1, gradientColors[Math.floor(Math.random() * gradientColors.length)]);
    ctx.fillStyle = gradient;
    ctx.fillRect(x, height - h, w, h);
