draw(ctx, width, height) {
  // Background
  ctx.fillStyle = '#0a0a0c';
  ctx.fillRect(0, 0, width, height);

  // Cached neon gradients
  const gradCache = {};
  function neonGrad(top, bot, color1, color2) {
    const key = `${top}-${bot}-${color1}-${color2}`;
    if (!gradCache[key]) {
      const g = ctx.createLinearGradient(0, top, 0, bot);
      g.addColorStop(0, color1);
      g.addColorStop(1, color2);
      gradCache[key] = g;
    }
    return gradCache[key];
  }

  // Skyscrapers
  const count = 90;
  ctx.lineWidth = 1;
  for (let i = 0; i < count; i++) {
    const x = (i / count) * width;
    const w = Math.random() * 30 + 10;
    const h = Math.random() * height * 0.7 + 50;
    const y = height - h;
    const neon = i % 2 === 0 ? ['#ff00ff', '#ff80ff'] : ['#00ffff', '#80ffff'];
    ctx.fillStyle = neonGrad(y, y + h, neon[0], neon[1]);
    ctx.fillRect(x, y, w, h);
    ctx.strokeStyle = neon[0];
    ctx.strokeRect(x, y, w, h);
  }

  // Rain
  ctx.strokeStyle = 'rgba(150, 200, 255, 0.4)';
  ctx.lineWidth = 0.5;
