  const gradientColors = [
    { offset: 0, color: 'rgba(128, 0, 128, 0.8)' }, // Purple
    { offset: 0.5, color: 'rgba(0, 255, 255, 0.8)' }, // Cyan
    { offset: 1, color: 'rgba(128, 0, 128, 0.8)' }, // Purple
  ];

  // Draw skyscrapers
  for (let i = 0; i < 20; i++) {
    const x = Math.random() * width;
    const w = Math.random() * 50 + 20;
    const h = Math.random() * (height / 2) + height / 4;
    const gradient = ctx.createLinearGradient(x, height, x, height - h);
    gradientColors.forEach(({ offset, color }) => gradient.addColorStop(offset, color));
    ctx.fillStyle = gradient;
    ctx.fillRect(x, height - h, w, h);
  }

  // Rain effects
  ctx.strokeStyle = 'rgba(0, 255, 255, 0.2)';
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  ctx.beginPath();
  for (let i = 0; i < 100; i++) {
    const x = Math.random() * width;
    const y = Math.random() * height;
    ctx.moveTo(x, y);
    ctx.lineTo(x, y + Math.random() * 20 + 10);
  }
  ctx.stroke();

  // Update rain effects for the next frame
  ctx.globalCompositeOperation = 'source-over';
}
