        const h = height * (0.4 + Math.random() * 0.4);
        const y = height - h;

        // neon gradient (purple → cyan)
        const grad = ctx.createLinearGradient(0, y, 0, y + h);
        grad.addColorStop(0, 'rgba(138,43,226,0.85)'); // deep purple
        grad.addColorStop(1, 'rgba(0,255,255,0.65)'); // cyan

        ctx.fillStyle = grad;
        ctx.fillRect(x, y, w, h);
    }

    // reset shadow for the rain
    ctx.shadowColor = 'transparent';
    ctx.shadowBlur = 0;

