function draw(ctx, width, height) {
  // Dark backdrop
  ctx.fillStyle = '#0a0a0c';
  ctx.fillRect(0, 0, width, height);

  // Neon skyscrapers
  const neonGradient = (x0, y0, x1, y1, color1, color2) => {
    const g = ctx.createLinearGradient(x0, y0, x1, y1);
    g.addColorStop(0, color1);
    g.addColorStop(1, color2);
    return g;
  };
  const count = Math.floor(width / 24);
  for (let i = 0; i < count; i++) {
    const w = 12 + Math.random() * 24;
    const x = i * (width / count) + Math.random() * 8;
    const h = 120 + Math.random() * (height * .6);
    const top = height - h;
    const glow = 10 + Math.random() * 10;
    // Glow
    ctx.shadowColor = Math.random() < .5 ? '#ff00ff' : '#00ffff';
    ctx.shadowBlur = glow;
    ctx.fillStyle = neonGradient(x, top, x, height, '#ff00ff', '#00ffff');
    ctx.fillRect(x, top, w, h);
    // Strip lights
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffffff';
    for (let j = 0; j < 5; j++) {
      const y = top + j * (h / 5) + 8;
      ctx.globalAlpha = .6;
      ctx.fillRect(x + 2, y, w - 4, 2);
    }
    ctx.globalAlpha = 1;
  }

  // Rain
  ctx.shadowColor = 'transparent';
  ctx.strokeStyle = 'rgba(0, 255, 255, .35)';
  ctx.lineWidth = 1;
  const drops = Math.floor(width * height / 3500);
  for (let i = 0; i < drops; i++) {
    const x = Math.random() * width;
    const y = Math.random() * height;
    const len = 12 + Math.random() * 24;
    ctx.globalAlpha = .3 + Math.random() * .4;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - 1, y + len);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}
