draw(ctx, width, height) {
  // 1. Dark sky
  ctx.fillStyle = '#0a0a0c';
  ctx.fillRect(0, 0, width, height);

  // Cached gradients
  function buildGradient(x0, y0, x1, y1, c0, c1) {
    const g = ctx.createLinearGradient(x0, y0, x1, y1);
    g.addColorStop(0, c0);
    g.addColorStop(1, c1);
    return g;
  }

  // 2. Skyscrapers
  const count = 70;
  const horizon = height * .68;
  for (let i = 0; i < count; i++) {
    const w = 4 + Math.random() * 22;
    const x = Math.random() * (width + 50) - 25;
    const h = 60 + Math.random() * (horizon * .8);
    const y = horizon - h;

    // purple or cyan
    const pal = Math.random() < .5;
    ctx.fillStyle = buildGradient(x, y, x, y + h,
      pal ? 'rgba(168, 50, 245,.85)' : 'rgba(0, 230, 255,.85)',
      pal ? 'rgba(168, 50, 245,.05)' : 'rgba(0, 230, 255,.05)');
    ctx.fillRect(x, y, w, h);

    // thin neon edge
    ctx.strokeStyle = pal ? 'rgba(217, 87, 255,.95)' : 'rgba(0, 255, 255,.95)';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(x, y, w, h);
  }

  // 3. Rain
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  const drops = 300;
  for (let i = 0; i < drops; i++) {
    const x = Math.random() * width;
    const y = Math.random() * height;
    const len = 12 + Math.random() * 25;
    ctx.strokeStyle = `rgba(200,240,255,${.08 + Math.random() * .12})`;
    ctx.lineWidth = Math.random() < .15 ? 1.5 : .8;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - 3, y + len);
    ctx.stroke();
  }
  ctx.restore();
}
