    const h = Math.random() * (height / 2) + (height / 4);
    const y = height - h;

    ctx.fillStyle = grd;
    ctx.fillRect(x, y, w, h);
  }

  // Draw rain effects
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 500; i++) {
    const x = Math.random() * width;
    const y = Math.random() * height;
    const len = Math.random() * 10 + 5;

    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x, y + len);
    ctx.stroke();
  }

  // Add glow effect to skyscrapers
  ctx.shadowColor = 'rgba(255, 255, 255, 0.5)';
  ctx.shadowBlur = 20;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;

  // Redraw skyscrapers with glow
  for (let i = 0; i < skyscraperCount; i++) {
    const x = (i / skyscraperCount) * width;
    const w = width / skyscraperCount;
    const h = Math.random() * (height / 2) + (height / 4);
    const y = height - h;

    ctx.fillStyle = grd;
    ctx.fillRect(x, y, w, h);
  }

  // Remove glow effect
  ctx.shadowBlur = 0;
}
