function draw(ctx, width, height) {
  // Set the canvas background to dark
  ctx.fillStyle = '#0a0a0c';
  ctx.fillRect(0, 0, width, height);

  // Define the skyscraper properties
  const skyscraperCount = 50;
  const minSkyscraperHeight = 100;
  const maxSkyscraperHeight = 500;
  const minSkyscraperWidth = 50;
  const maxSkyscraperWidth = 200;
  const skyscraperSpacing = 20;

  // Draw skyscrapers
  for (let i = 0; i < skyscraperCount; i++) {
    const x = (i * (maxSkyscraperWidth + skyscraperSpacing)) + (maxSkyscraperWidth / 2);
    const height = Math.floor(Math.random() * (maxSkyscraperHeight - minSkyscraperHeight)) + minSkyscraperHeight;
    const width = Math.floor(Math.random() * (maxSkyscraperWidth - minSkyscraperWidth)) + minSkyscraperWidth;

    // Draw the skyscraper body
    ctx.fillStyle = `linear-gradient(to bottom, #7a288a, #4c4c4c)`;
    ctx.fillRect(x, height, width, height);

    // Draw the skyscraper top
    ctx.fillStyle = `linear-gradient(to bottom, #00ffff, #4c4c4c)`;
    ctx.fillRect(x, height - 50, width, 50);
  }

  // Define the rain properties
  const rainCount = 100;
  const minRainLength = 10;
  const maxRainLength = 50;
  const minRainSpacing = 5;
  const maxRainSpacing = 20;

  // Draw rain
  for (let i = 0; i < rainCount; i++) {
    const x = Math.floor(Math.random() * (width - 1));
    const y = Math.floor(Math.random() * (height - 1));
    const length = Math.floor(Math.random() * (maxRainLength - minRainLength)) + minRainLength;
    const spacing = Math.floor(Math.random() * (maxRainSpacing - minRainSpacing)) + minRainSpacing;

    // Draw the rain line
    ctx.strokeStyle = `rgba(255, 255, 255, 0.1)`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x, y + length);
    ctx.stroke();
  }
}
